<?php use backend\models\StudentSemesterStatus;use kartik\grid\GridView;use yii\helpers\{Html,Url};$this->title='Data Status Semester';?>
<div class="d-flex justify-content-between mb-3"><h1><?=$this->title?></h1><div><?=Html::a('Kembali ke Rekap',['index','academic_period'=>$academic_period],['class'=>'btn btn-primary'])?> <?=Html::a('<i class="fas fa-plus"></i> Tambah',['create'],['class'=>'btn btn-success'])?></div></div><?=GridView::widget(['dataProvider'=>$dataProvider,'panel'=>['heading'=>'Daftar Status Semester','type'=>GridView::TYPE_DARK],'columns'=>[['label'=>'NIM','value'=>static fn($m)=>$m->student->student_nationality_number],['label'=>'Mahasiswa','value'=>static fn($m)=>$m->student->user->name],['label'=>'Program Studi','value'=>static fn($m)=>$m->studyProgram->name],'academic_period','semester',['attribute'=>'status','value'=>static fn($m)=>StudentSemesterStatus::statusOptions()[$m->status]],['class'=>'kartik\grid\ActionColumn','template'=>'{view} {update} {delete}','buttons'=>['delete'=>static fn($url)=>Html::button('<i class="fas fa-trash"></i>',['class'=>'btn btn-danger btn-sm js-delete-status','data-url'=>$url])]]]])?>
<?php $js=<<<'JS'
$(document).on('click','.js-delete-status',function(){var url=$(this).data('url');Swal.fire({title:'Hapus Status Semester?',text:'Data yang dihapus tidak dapat dikembalikan.',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, Hapus',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;$.post(url,{_csrf:yii.getCsrfToken()}).done(function(x){Swal.fire('Berhasil',x.message,'success').then(function(){location.reload();});});});});
JS;$this->registerJs($js);?>
